-- Gamification groundwork:
--   * streak freezes become per language and remember the day they were
--     earned, so the streak fold can rebuild them wholesale (one per week of
--     study, two at most) instead of re-spending an undated pool each time;
--   * an achievement remembers when its unlock was shown, so it is celebrated
--     once;
--   * two new notification switches: the evening streak-at-risk nudge and the
--     weekly note about cards that keep being forgotten.
--
-- Generated by drizzle-kit, then made idempotent by hand. Additive: nullable
-- or defaulted columns, one foreign key, one index. No freeze rows exist yet
-- (nothing ever wrote them), so there is nothing to backfill.

ALTER TABLE "streak_freezes" ADD COLUMN IF NOT EXISTS "language_id" text;--> statement-breakpoint
ALTER TABLE "streak_freezes" ADD COLUMN IF NOT EXISTS "earned_on" date;--> statement-breakpoint
ALTER TABLE "user_achievements" ADD COLUMN IF NOT EXISTS "seen_at" timestamp;--> statement-breakpoint
ALTER TABLE "user_settings" ADD COLUMN IF NOT EXISTS "streak_risk_enabled" boolean DEFAULT true NOT NULL;--> statement-breakpoint
ALTER TABLE "user_settings" ADD COLUMN IF NOT EXISTS "ghost_alert_enabled" boolean DEFAULT true NOT NULL;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "streak_freezes" ADD CONSTRAINT "streak_freezes_language_id_languages_id_fk" FOREIGN KEY ("language_id") REFERENCES "public"."languages"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "streak_freezes_earned_unique" ON "streak_freezes" USING btree ("user_id","language_id","reason","earned_on");
